"use client";

import { useState } from "react";

export function CreditCardTailwind() {
  const [pos, setPos] = useState({ x: 50, y: 85 });
  return (
    <div
      onPointerMove={(e) => {
        const r = e.currentTarget.getBoundingClientRect();
        setPos({ x: ((e.clientX - r.left) / r.width) * 100, y: ((e.clientY - r.top) / r.height) * 100 });
      }}
      onPointerLeave={() => setPos({ x: 50, y: 85 })}
      style={{ backgroundImage: `radial-gradient(circle at ${pos.x}% ${pos.y}%, rgba(255,138,31,0.55), transparent 45%)` }}
      className="relative flex aspect-[1.586] w-96 flex-col justify-between rounded-2xl border border-white/5 bg-stone-900 p-7 font-mono text-stone-100 transition-[background-image]"
    >
      <div className="flex justify-between text-xs tracking-widest text-stone-400">
        MOTIONFOUNDRY <span className="h-9 w-12 rounded-md bg-amber-700" />
      </div>
      <div className="text-2xl tracking-widest">4242 4242 4242 4242</div>
      <div className="flex justify-between text-xs tracking-widest text-stone-400">
        <span>ALEX MORGAN</span>
        <span>12/28</span>
      </div>
    </div>
  );
}
